import{_ as i,o as a,c as n,ag as t}from"./chunks/framework.BZohXCq9.js";const c=JSON.parse('{"title":"RKNN 输入到底是 FP32、FP16 还是 INT8","description":"分清模型精度、Runtime 输入类型与 NPU 内部计算精度，并用 rknn_query 获取真实合同","frontmatter":{"title":"RKNN 输入到底是 FP32、FP16 还是 INT8","description":"分清模型精度、Runtime 输入类型与 NPU 内部计算精度，并用 rknn_query 获取真实合同","tags":["RK3588","RKNN","NPU","FP16","INT8"],"date":"2026/07/16"},"headers":[],"relativePath":"linux/rknn-input-dtype.md","filePath":"linux/rknn-input-dtype.md","lastUpdated":1784519165000}'),e={name:"linux/rknn-input-dtype.md"};function p(l,s,h,r,k,o){return a(),n("div",null,[...s[0]||(s[0]=[t(`<h1 id="rknn-输入到底是-fp32、fp16-还是-int8" tabindex="-1">RKNN 输入到底是 FP32、FP16 还是 INT8 <a class="header-anchor" href="#rknn-输入到底是-fp32、fp16-还是-int8" aria-label="Permalink to &quot;RKNN 输入到底是 FP32、FP16 还是 INT8&quot;">​</a></h1><p>“这个 RKNN 模型输入是 FP32、FP16 还是 INT8？”看似是一个类型问题，实际混在一起的至少有三层：模型如何量化、Runtime API 接受什么、NPU 最终怎样计算。</p><h2 id="先拆开三个概念" tabindex="-1">先拆开三个概念 <a class="header-anchor" href="#先拆开三个概念" aria-label="Permalink to &quot;先拆开三个概念&quot;">​</a></h2><h3 id="_1-模型精度" tabindex="-1">1. 模型精度 <a class="header-anchor" href="#_1-模型精度" aria-label="Permalink to &quot;1. 模型精度&quot;">​</a></h3><p>模型转换时决定权重与算子的精度，例如非量化模型或 INT8 量化模型。它描述的是 <code>.rknn</code> 图的属性。</p><h3 id="_2-runtime-输入-dtype" tabindex="-1">2. Runtime 输入 dtype <a class="header-anchor" href="#_2-runtime-输入-dtype" aria-label="Permalink to &quot;2. Runtime 输入 dtype&quot;">​</a></h3><p>应用传给 <code>rknn_inputs_set()</code> 或 zero-copy buffer 的数据类型，例如 <code>RKNN_TENSOR_FLOAT32</code>、<code>FLOAT16</code>、<code>INT8</code>、<code>UINT8</code>。</p><h3 id="_3-npu-内部计算精度" tabindex="-1">3. NPU 内部计算精度 <a class="header-anchor" href="#_3-npu-内部计算精度" aria-label="Permalink to &quot;3. NPU 内部计算精度&quot;">​</a></h3><p>Runtime 可能在进入 NPU 前做类型和 layout 转换。应用传 FP32，不等于整个网络就在 NPU 上以 FP32 执行。</p><p>因此，不能只根据“模型是 FP16”就猜应用 buffer 一定是 FP16，也不能只看到 API 传 FP32 就认定模型未量化。</p><h2 id="唯一可靠的入口-查询模型属性" tabindex="-1">唯一可靠的入口：查询模型属性 <a class="header-anchor" href="#唯一可靠的入口-查询模型属性" aria-label="Permalink to &quot;唯一可靠的入口：查询模型属性&quot;">​</a></h2><p>初始化 context 后，查询输入 tensor：</p><div class="language-cpp vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">cpp</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">rknn_input_output_num io_num{};</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">rknn_query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, RKNN_QUERY_IN_OUT_NUM, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">io_num, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(io_num));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">for</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">uint32_t</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; i </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> io_num.n_input; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">++</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">i) {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    rknn_tensor_attr attr{};</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    attr.index </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> i;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    rknn_query</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(ctx, RKNN_QUERY_INPUT_ATTR, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">attr, </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(attr));</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    printf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;input[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">] type=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> fmt=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%d</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> dims=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> size=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%u</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> stride=</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">%u\\n</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           i, attr.type, attr.fmt, attr.n_dims,</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">           attr.size, attr.size_with_stride);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>重点检查：</p><ul><li><code>attr.type</code>：native dtype；</li><li><code>attr.fmt</code>：NCHW / NHWC 等 layout；</li><li><code>attr.dims</code>：维度顺序；</li><li><code>attr.size_with_stride</code>：实际 buffer 容量；</li><li>量化参数，如 scale 与 zero point。</li></ul><h2 id="pass-through-0-为什么能传-fp32" tabindex="-1"><code>pass_through=0</code> 为什么能传 FP32 <a class="header-anchor" href="#pass-through-0-为什么能传-fp32" aria-label="Permalink to &quot;\`pass_through=0\` 为什么能传 FP32&quot;">​</a></h2><p>普通 <code>rknn_inputs_set()</code> 路径中，<code>pass_through=0</code> 允许 Runtime 根据描述做预处理或类型转换。应用可以传 FP32，Runtime 再转成模型需要的类型。</p><p>这让接口更易用，但转换会消耗 CPU 和内存带宽。如果前处理原本就在 RGA/OpenCL 上，随后又把数据交给 Runtime 做一次 layout/dtype 转换，zero-copy 的意义会被削弱。</p><h2 id="高性能路径的原则" tabindex="-1">高性能路径的原则 <a class="header-anchor" href="#高性能路径的原则" aria-label="Permalink to &quot;高性能路径的原则&quot;">​</a></h2><p>对于固定模型的板端部署，尽量让上游直接产出模型 native contract：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>图像采集</span></span>
<span class="line"><span>  → resize / crop</span></span>
<span class="line"><span>  → color convert</span></span>
<span class="line"><span>  → normalize / quantize（按模型要求）</span></span>
<span class="line"><span>  → native dtype + native layout buffer</span></span>
<span class="line"><span>  → RKNN zero-copy input</span></span></code></pre></div><p>但不要为了“少一次转换”凭经验硬编码 INT8 或 FP16。先查询 <code>.rknn</code>，再决定 OpenCL/RGA 输出格式和 buffer stride。</p><h2 id="常见误区" tabindex="-1">常见误区 <a class="header-anchor" href="#常见误区" aria-label="Permalink to &quot;常见误区&quot;">​</a></h2><ul><li><strong>“RK3588 NPU 固定吃 INT8”</strong>：错误，取决于模型与 runtime 合同；</li><li><strong>“FP16 模型就必须从相机直接给 FP16”</strong>：不一定，API 可能允许 FP32 转换；</li><li><strong>“UINT8 输入代表模型一定是 UINT8 量化”</strong>：还要结合量化参数和转换路径；</li><li><strong>只看 <code>size</code> 不看 <code>size_with_stride</code></strong>：zero-copy buffer 容易越界或产生错位；</li><li><strong>把模型精度与内部算子精度画等号</strong>：Runtime 与硬件可能做混合精度处理。</li></ul><h2 id="建议的验收" tabindex="-1">建议的验收 <a class="header-anchor" href="#建议的验收" aria-label="Permalink to &quot;建议的验收&quot;">​</a></h2><ol><li>打印每个输入/输出 tensor attr；</li><li>固定一组输入，比较普通输入与 zero-copy 结果；</li><li>测量 Runtime 转换前后的 CPU 与延迟；</li><li>验证 stride、layout 和量化参数；</li><li>把模型 hash 与 attr dump 一起纳入部署记录。</li></ol><p>结论很简单：<strong>RKNN 输入类型不是平台常量，而是模型文件与调用路径共同定义的运行时合同。</strong></p><p>参考：<a href="https://github.com/airockchip/rknn-toolkit2" target="_blank" rel="noreferrer">RKNN-Toolkit2 官方仓库</a>。</p>`,28)])])}const u=i(e,[["render",p]]);export{c as __pageData,u as default};
